// Pick the app icon key for a file record's type.
function appIconKeyForType(type) {
  if (type === "video") return "video";
  if (type === "markdown") return "markdown";
  return "image";
}

function appIconHtml(iconKey, extraClass = "") {
  const key = String(iconKey || "noItem");
  const svg = APP_ICON_SVGS[key] || APP_ICON_SVGS.noItem;
  const classes = ["appIcon", `appIcon-${key}`];
  const extra = String(extraClass || "").trim();
  if (extra) classes.push(extra);
  return `<span class="${classes.map(escapeHtml).join(" ")}" aria-hidden="true">${svg}</span>`;
}

// The type icon, then a mark for each state the card is in: Hidden, and one
// more (`lockIconKey`): a Tag's lock (tagLockIconKey: Model only or Root only)
// or a stored folder's storage icon. A marked bubble widens to fit.
function thumbnailTypeIconBubbleHtml(iconKey, isHidden = false, lockIconKey = "") {
  const hidden = !!isHidden;
  const lock = String(lockIconKey || "");
  return `<span class="thumbnailTitleTypeIcon thumbnailTypeIconBubble${hidden || lock ? " thumbnailTypeIconBubbleHidden" : ""}" aria-hidden="true">${appIconHtml(iconKey, "thumbnailTypeIconGlyph")}${hidden ? appIconHtml("hidden", "thumbnailHiddenGlyph") : ""}${lock ? appIconHtml(lock, "thumbnailHiddenGlyph thumbnailTagLockGlyph") : ""}</span>`;
}

function itemTypeIconHtml(iconKey, isHidden = false, lockIconKey = "") {
  return `${appIconHtml(iconKey)}${isHidden ? appIconHtml("hidden", "dirHiddenIconGlyph") : ""}${lockIconKey ? appIconHtml(lockIconKey, "dirHiddenIconGlyph") : ""}`;
}

// The Model only and Root only switches' icons, used for their menu rows and
// their card marks.
const MODEL_ONLY_ICON_KEY = "luMapPin";
const ROOT_ONLY_ICON_KEY = "luHouse";

function tagLockIconKey(name) {
  if (tagIsRootOnly(name)) return ROOT_ONLY_ICON_KEY;
  if (tagIsModelOnly(name)) return MODEL_ONLY_ICON_KEY;
  return "";
}

const MEDIA_CONTROL_ICON_SVGS = Object.freeze({
  play: '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-play-icon lucide-play"><path d="M5 5a2 2 0 0 1 3.008-1.728l11.997 6.998a2 2 0 0 1 .003 3.458l-12 7A2 2 0 0 1 5 19z"/></svg>',
  pause: '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-pause-icon lucide-pause"><rect x="14" y="3" width="5" height="18" rx="1"/><rect x="5" y="3" width="5" height="18" rx="1"/></svg>',
  fastForward: '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-fast-forward-icon lucide-fast-forward"><path d="M12 6a2 2 0 0 1 3.414-1.414l6 6a2 2 0 0 1 0 2.828l-6 6A2 2 0 0 1 12 18z"/><path d="M2 6a2 2 0 0 1 3.414-1.414l6 6a2 2 0 0 1 0 2.828l-6 6A2 2 0 0 1 2 18z"/></svg>',
  rewind: '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-rewind-icon lucide-rewind"><path d="M12 6a2 2 0 0 0-3.414-1.414l-6 6a2 2 0 0 0 0 2.828l6 6A2 2 0 0 0 12 18z"/><path d="M22 6a2 2 0 0 0-3.414-1.414l-6 6a2 2 0 0 0 0 2.828l6 6A2 2 0 0 0 22 18z"/></svg>',
  skipForward: '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-skip-forward-icon lucide-skip-forward"><path d="M21 4v16"/><path d="M6.029 4.285A2 2 0 0 0 3 6v12a2 2 0 0 0 3.029 1.715l9.997-5.998a2 2 0 0 0 .003-3.432z"/></svg>',
  volumeOn: '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-volume2-icon lucide-volume-2"><path d="M11 5 6 9H2v6h4l5 4z"/><path d="M19.07 4.93a10 10 0 0 1 0 14.14"/><path d="M15.54 8.46a5 5 0 0 1 0 7.07"/></svg>',
  volumeOff: '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-volume-x-icon lucide-volume-x"><path d="M11 5 6 9H2v6h4l5 4z"/><path d="m22 9-6 6"/><path d="m16 9 6 6"/></svg>',
});

function mediaControlIconHtml(iconKey, extraClass = "") {
  const key = String(iconKey || "play");
  const svg = MEDIA_CONTROL_ICON_SVGS[key] || MEDIA_CONTROL_ICON_SVGS.play;
  const classes = ["controlIcon"];
  const extra = String(extraClass || "").trim();
  if (extra) classes.push(extra);
  return `<span class="${classes.map(escapeHtml).join(" ")}" aria-hidden="true">${svg}</span>`;
}

function setMediaControlButtonHtml(button, html) {
  if (!button || button.innerHTML === html) return;
  button.innerHTML = html;
}

function setMediaControlIconButton(button, iconKey, extraClass = "") {
  if (!button) return;
  const key = String(iconKey || "play");
  const extra = String(extraClass || "").trim();
  if (
    button.dataset.controlIconKey === key &&
    button.dataset.controlIconExtra === extra
  ) {
    return;
  }
  setMediaControlButtonHtml(button, mediaControlIconHtml(key, extra));
  button.dataset.controlIconKey = key;
  button.dataset.controlIconExtra = extra;
}

function setAppIcon(el, iconKey) {
  if (!el) return;
  el.textContent = "";
  el.innerHTML = appIconHtml(iconKey);
}

/* The title is built as text alone. The type icon arrives as a bubble
   mounted by `mountPendingThumbnailTypeIcons` below (some card builders write
   the bubble into their markup instead), and `arrangeCardPills` then moves
   its glyph into the name's pill.

   It has to move in the *markup*, not with CSS. The title pill carries a
   `backdrop-filter`, and an element with a backdrop-filter is a containing
   block for absolutely positioned descendants even when it is `position:
   static` -- so an icon left inside the pill anchors to the pill however the
   stylesheet is written, and lands in its top-left corner rather than the
   card's. There is no CSS escape from a containing block. */
function thumbnailTitleHtml(iconKey, label) {
  return `<span class="thumbnailTitleText">${escapeHtml(String(label || ""))}</span>`;
}

/* The title records which icon it wants and the bubble is mounted afterwards.

   It cannot be mounted here: a card is assembled detached and appended to the
   document at the end, so at this point the title has no card to look up to.
   The pass is scheduled as a microtask, which runs once the render function
   that built the cards has returned and they are in the DOM -- and it is
   idempotent, because it only handles titles still carrying the attribute, so
   a chunked render that calls this a hundred times still does one pass per
   batch. */
const THUMB_TYPE_ICON_HOSTS =
  ".previewThumbOverlayMeta, .thumbOverlayMeta, .dirSquareOverlay," +
  " .dirFileOverlay, .previewItemPlaceholderInfoBar";
let THUMB_TYPE_ICON_MOUNT_QUEUED = false;

function mountPendingThumbnailTypeIcons() {
  THUMB_TYPE_ICON_MOUNT_QUEUED = false;
  const pending = document.querySelectorAll(
    ".thumbnailTitleWithIcon[data-type-icon]",
  );
  for (const titleEl of pending) {
    const key = titleEl.getAttribute("data-type-icon") || "";
    const isHidden = titleEl.getAttribute("data-hidden-icon") === "1";
    const markIcon = titleEl.getAttribute("data-mark-icon") || "";
    titleEl.removeAttribute("data-type-icon");
    titleEl.removeAttribute("data-hidden-icon");
    titleEl.removeAttribute("data-mark-icon");
    const host = titleEl.closest(THUMB_TYPE_ICON_HOSTS);
    if (!host) continue;
    const existing = host.querySelector(":scope > .thumbnailTypeIconBubble");
    if (existing) existing.remove();
    host.insertAdjacentHTML(
      "afterbegin",
      thumbnailTypeIconBubbleHtml(key, isHidden, markIcon),
    );
  }
}

/* What shares the name's pill. Icon placement In name puts the type icon in
   it, before the name; Score placement In name puts the score in it, between
   the icon and the name. Every card gets its icon as a
   `.thumbnailTypeIconBubble` in its overlay -- mounted by the pass above or
   written straight into a builder's markup -- and its score as the inert
   `.dirMenuBtn` badge in the overlay's bottom row, so one observer arranges
   them all rather than each builder learning to. It runs as a microtask,
   before the frame is painted, so the other arrangement is never seen. A card
   with no name pill keeps its bubble and its badge where they were built. */
const CARD_SCORE_BADGE_SELECTOR = ".dirMenuBtn.thumbMenuBtnInert";

function arrangeCardPills(host) {
  if (!host || !host.isConnected) return;
  const title = host.querySelector(".thumbnailTitleWithIcon");
  if (!title) return;
  const iconInName = typeIconPlacement() === "name";
  const scoreInName = scorePlacement() === "name";
  // The type icon.
  const bubble = host.querySelector(":scope > .thumbnailTypeIconBubble");
  const glyphs = Array.from(
    title.querySelectorAll(":scope > .thumbnailTitleTypeIcon"),
  );
  if (iconInName && bubble) {
    glyphs.forEach((el) => el.remove());
    const moved = Array.from(bubble.children);
    moved.forEach((el) => el.classList.add("thumbnailTitleTypeIcon"));
    title.prepend(...moved);
    bubble.remove();
  } else if (!iconInName && glyphs.length) {
    glyphs.forEach((el) => el.remove());
    if (!bubble) {
      const back = document.createElement("span");
      back.className = "thumbnailTitleTypeIcon thumbnailTypeIconBubble";
      if (glyphs.some((el) => el.classList.contains("thumbnailHiddenGlyph")))
        back.classList.add("thumbnailTypeIconBubbleHidden");
      back.setAttribute("aria-hidden", "true");
      glyphs.forEach((el) => el.classList.remove("thumbnailTitleTypeIcon"));
      back.append(...glyphs);
      host.prepend(back);
    }
  }
  // The score, between the icon and the name.
  const inTitle = title.querySelector(`:scope > ${CARD_SCORE_BADGE_SELECTOR}`);
  if (scoreInName && !inTitle) {
    const badge = host.querySelector(CARD_SCORE_BADGE_SELECTOR);
    if (!badge) return;
    badge._lgScoreHome = badge.parentElement;
    title.insertBefore(badge, title.querySelector(":scope > .thumbnailTitleText"));
  } else if (!scoreInName && inTitle) {
    const home = inTitle._lgScoreHome;
    if (home && home.isConnected && host.contains(home)) home.appendChild(inTitle);
    else inTitle.remove();
  }
}

// Every card overlay at or inside `node`, arranged.
function arrangeCardPillsIn(node) {
  if (!node || node.nodeType !== 1) return;
  const hosts = new Set();
  const own = node.closest(THUMB_TYPE_ICON_HOSTS);
  if (own) hosts.add(own);
  if (node.firstElementChild)
    node.querySelectorAll(THUMB_TYPE_ICON_HOSTS).forEach((host) => hosts.add(host));
  hosts.forEach(arrangeCardPills);
}

new MutationObserver((records) => {
  for (const record of records) {
    for (const node of record.addedNodes) arrangeCardPillsIn(node);
  }
}).observe(document.documentElement, { childList: true, subtree: true });

function queueThumbnailTypeIconMount() {
  if (THUMB_TYPE_ICON_MOUNT_QUEUED) return;
  THUMB_TYPE_ICON_MOUNT_QUEUED = true;
  queueMicrotask(mountPendingThumbnailTypeIcons);
}

function setThumbnailTitle(el, iconKey, label, opts = null) {
  if (!el) return;
  el.classList.add("thumbnailTitleWithIcon");
  el.setAttribute("data-type-icon", String(iconKey || ""));
  if (opts && opts.hidden) el.setAttribute("data-hidden-icon", "1");
  else el.removeAttribute("data-hidden-icon");
  // A second mark beside the type icon (a stored folder's storage icon).
  if (opts && opts.markIcon) el.setAttribute("data-mark-icon", String(opts.markIcon));
  else el.removeAttribute("data-mark-icon");
  el.innerHTML = thumbnailTitleHtml(iconKey, label);
  queueThumbnailTypeIconMount();
}

function iconKeyForRecordType(type) {
  const t = String(type || "");
  if (t === "video") return "video";
  if (t === "markdown") return "markdown";
  return "image";
}

function iconKeyForDirNode(node) {
  // A stored folder is still a folder; its storage mark sits beside the icon.
  if (isTrashRootPortalNode(node)) return "trash";
  if (node && node._skipTagFilters) {
    const mode = String(node._tagPreviewMode || "");
    if (mode === "album") return "album";
    if (mode === "gallery") return "gallery";
    if (mode === "favorites") return "favorite";
    if (mode === "hidden") return "hidden";
    if (mode === "untagged") return "untagged";
    if (mode === "storage") return "storage";
    return "tag";
  }
  return "folder";
}

function favoriteHeartSymbol(opt = null) {
  return appIconHtml("favorite");
}

function favoriteMenuButtonLabel(opt = null) {
  return `<span class="dirMenuFavoriteGlyph" aria-hidden="true">${favoriteHeartSymbol(opt)}</span>`;
}

const FAVORITE_MENU_BUTTON_DISPLAY_ICON = "icon";
const FAVORITE_MENU_BUTTON_DISPLAY_TINT = "tint";

function thumbnailMenuButtonScoreEnabled(opt = null) {
  const src = opt || (WS.meta && WS.meta.options ? WS.meta.options : null);
  return scoreInterfaceEnabled(src) && !(src && src.showScores === false);
}

function formatThumbnailMenuButtonScoreValue(scoreValue) {
  const n = Number(scoreValue);
  if (!Number.isFinite(n)) return "";
  return String(Math.round(n));
}

// A score of 0 is the score every item starts with, so it says nothing: a card
// shows its score only once it is something else.
function thumbnailMenuButtonShowsScore(scoreValue, opt = null) {
  const text = formatThumbnailMenuButtonScoreValue(scoreValue);
  return thumbnailMenuButtonScoreEnabled(opt) && !!text && text !== "0";
}

function formatSystemPortalItemCountLabel(count) {
  const n = Math.max(0, Math.round(Number(count) || 0));
  return `${n} item${n === 1 ? "" : "s"}`;
}

function thumbnailMenuButtonLabelHtml(
  scoreValue,
  isFavorite = false,
  opt = null,
  favoriteDisplay = FAVORITE_MENU_BUTTON_DISPLAY_ICON,
  labelText = "",
) {
  const customLabel = String(labelText || "").trim();
  const scoreText = thumbnailMenuButtonShowsScore(scoreValue, opt)
    ? formatThumbnailMenuButtonScoreValue(scoreValue)
    : "";
  if (customLabel) {
    return `
    <span class="dirMenuBtnScoreLabel dirMenuBtnCountLabel">
      <span class="dirMenuBtnScoreText dirMenuBtnCountText">${escapeHtml(customLabel)}</span>
    </span>
  `;
  }
  const useFavoriteIcon =
    isFavorite && favoriteDisplay === FAVORITE_MENU_BUTTON_DISPLAY_ICON;
  if (!scoreText) return useFavoriteIcon ? favoriteMenuButtonLabel(opt) : "⋯";
  return `
    <span class="dirMenuBtnScoreLabel${isFavorite ? " dirMenuBtnScoreLabelFavorite" : ""}">
      ${
        useFavoriteIcon
          ? `<span class="dirMenuBtnScoreHeart" aria-hidden="true">${favoriteHeartSymbol(opt)}</span>`
          : ""
      }
      <span class="dirMenuBtnScoreText">${escapeHtml(scoreText)}</span>
    </span>
  `;
}

function thumbnailMenuButtonClassName(
  extraClasses = "",
  scoreValue = null,
  isFavorite = false,
  opt = null,
  favoriteDisplay = FAVORITE_MENU_BUTTON_DISPLAY_ICON,
  labelText = "",
) {
  const classes = ["dirMenuBtn"].concat(
    String(extraClasses || "")
      .split(/\s+/)
      .filter(Boolean),
  );
  const hasCustomLabel = !!String(labelText || "").trim();
  const showScore = thumbnailMenuButtonShowsScore(scoreValue, opt);
  const showBadgeText = showScore || hasCustomLabel;
  if (showBadgeText) classes.push("dirMenuBtnScoreVisible");
  if (isFavorite && !showBadgeText) {
    classes.push(
      favoriteDisplay === FAVORITE_MENU_BUTTON_DISPLAY_TINT
        ? "dirMenuBtnFavoriteTint"
        : "dirMenuBtnFavorite",
    );
  }
  if (isFavorite && showBadgeText) {
    classes.push(
      favoriteDisplay === FAVORITE_MENU_BUTTON_DISPLAY_TINT
        ? "dirMenuBtnScoreFavoriteTint"
        : "dirMenuBtnScoreFavorite",
    );
  }
  return classes.join(" ");
}

function configureThumbnailMenuButton(
  btn,
  title,
  scoreValue = null,
  isFavorite = false,
  extraClasses = "",
  opt = null,
  favoriteDisplay = FAVORITE_MENU_BUTTON_DISPLAY_ICON,
  labelText = "",
) {
  if (!btn) return;
  btn.className = thumbnailMenuButtonClassName(
    extraClasses,
    scoreValue,
    isFavorite,
    opt,
    favoriteDisplay,
    labelText,
  );
  btn.innerHTML = thumbnailMenuButtonLabelHtml(
    scoreValue,
    isFavorite,
    opt,
    favoriteDisplay,
    labelText,
  );
  btn.title = String(title || "");
  // With the item menu folded into the app menu there is nothing for this
  // button to open, so it stays as a badge. It is deliberately NOT `disabled`:
  // that would pull in the sheet's disabled-button dimming and render it
  // translucent. pointer-events:none already makes it unclickable, and
  // tabindex/aria keep it out of the tab order and the a11y tree.
  if (separateItemMenuDisabled()) {
    btn.classList.add("thumbMenuBtnInert");
    btn.tabIndex = -1;
    btn.setAttribute("aria-hidden", "true");
    btn.title = "";
  }
}

function buildThumbnailMenuButtonHtml(
  title,
  scoreValue = null,
  isFavorite = false,
  extraClasses = "",
  disabled = false,
  opt = null,
  favoriteDisplay = FAVORITE_MENU_BUTTON_DISPLAY_ICON,
  labelText = "",
) {
  return `<button class="${escapeHtml(
    thumbnailMenuButtonClassName(
      extraClasses,
      scoreValue,
      isFavorite,
      opt,
      favoriteDisplay,
      labelText,
    ),
  )}${separateItemMenuDisabled() ? " thumbMenuBtnInert" : ""}" title="${escapeHtml(
    separateItemMenuDisabled() ? "" : String(title || ""),
  )}"${
    separateItemMenuDisabled()
      ? ' tabindex="-1" aria-hidden="true"'
      : disabled
        ? " disabled"
        : ""
  }>${thumbnailMenuButtonLabelHtml(
    scoreValue,
    isFavorite,
    opt,
    favoriteDisplay,
    labelText,
  )}</button>`;
}

function syncMountedThumbColorFilters() {
  try {
    const thumbImgs = document.querySelectorAll(
      'img.folderThumb, img.dirInlinePreview, img[data-dir-preview-id], img[data-file-id], img.thumb'
    );
    thumbImgs.forEach((img) => {
      const recId = String(
        img.dataset.dirPreviewId || img.dataset.fileId || ""
      );
      if (!recId) return;
      const rec = WS.fileById.get(recId);
      if (!rec) return;
      const colF = getCurrentColorFilterCssForTarget(rec);
      if (colF) {
        try { img.style.filter = colF; } catch {}
      } else {
        try { img.style.removeProperty("filter"); } catch {}
      }
    });
  } catch {}
}

function scheduleMountedThumbColorFilterSync() {
  if (MEDIA_FILTER_THUMB_SYNC_TIMER) clearTimeout(MEDIA_FILTER_THUMB_SYNC_TIMER);
  MEDIA_FILTER_THUMB_SYNC_TIMER = setTimeout(() => {
    MEDIA_FILTER_THUMB_SYNC_TIMER = null;
    syncMountedThumbColorFilters();
  }, 120);
}
